import './progress-ring.css';

export interface ProgressRingProps {
  /** 0 to 100. */
  value: number;
  /** Accessible name, for example "Upload progress". */
  label: string;
  /** Diameter in pixels. */
  size?: number;
  /** Ring thickness in pixels. */
  stroke?: number;
  className?: string;
}

/** A ring that animates to the given percentage. */
export function ProgressRing({
  value,
  label,
  size = 120,
  stroke = 10,
  className = '',
}: ProgressRingProps) {
  const percent = Math.max(0, Math.min(100, value));
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  return (
    <div
      className={`mg-ring ${className}`}
      role='progressbar'
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(percent)}
      style={{ width: size, height: size }}
    >
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        aria-hidden='true'
      >
        <circle
          className='mg-ring__track'
          cx={size / 2}
          cy={size / 2}
          r={radius}
          strokeWidth={stroke}
        />
        <circle
          className='mg-ring__value'
          cx={size / 2}
          cy={size / 2}
          r={radius}
          strokeWidth={stroke}
          strokeDasharray={circumference}
          strokeDashoffset={circumference * (1 - percent / 100)}
        />
      </svg>
      <span className='mg-ring__label' aria-hidden='true'>
        {Math.round(percent)}%
      </span>
    </div>
  );
}

.mg-ring {
  position: relative;
  display: inline-grid;
  place-items: center;
}

.mg-ring svg {
  position: absolute;
  inset: 0;
  /* Start the ring at twelve o'clock. */
  transform: rotate(-90deg);
}

.mg-ring__track,
.mg-ring__value {
  fill: none;
}

.mg-ring__track {
  stroke: var(--mg-track, #303030);
}

.mg-ring__value {
  stroke: var(--mg-accent-text, #dce9f7);
  stroke-linecap: round;
  transition: stroke-dashoffset 700ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-ring__label {
  color: var(--mg-text, #ffffff);
  font-size: 1.4em;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

@media (prefers-reduced-motion: reduce) {
  .mg-ring__value {
    transition: none;
  }
}
